TEST(compile_test, text_and_arg) {
  EXPECT_EQ(">>>42<<<", fmt::format(FMT_COMPILE(">>>{}<<<"), 42));
  EXPECT_EQ("42!", fmt::format(FMT_COMPILE("{}!"), 42));
}

TEST(compile_test, nullptr_formatting) {
  auto bare = fmt::format(fmt::runtime("{}"), nullptr);
  auto surrounded = fmt::format(fmt::runtime("[{}]"), nullptr);
  EXPECT_EQ("0x0", bare);
  EXPECT_EQ(bare, fmt::format(FMT_COMPILE("{}"), nullptr));
  EXPECT_EQ(surrounded, fmt::format(FMT_COMPILE("[{}]"), nullptr));
  EXPECT_EQ(fmt::format(fmt::runtime("[{:>8p}]"), nullptr),
            fmt::format(FMT_COMPILE("[{:>8p}]"), nullptr));

  std::vector<char> output;
  fmt::format_to(std::back_inserter(output), FMT_COMPILE("{}"), nullptr);
  EXPECT_EQ(bare, std::string(output.begin(), output.end()));

  char buffer[6] = {'x', 'x', 'x', 'x', 'x', 'x'};
  char* out = buffer;
  auto end = fmt::format_to(out, FMT_COMPILE("[{}]"), nullptr);
  EXPECT_EQ(buffer + surrounded.size(), end);
  EXPECT_EQ(surrounded, std::string(buffer, surrounded.size()));
  EXPECT_EQ('x', buffer[5]);

  auto result = fmt::format_to_n(out, 5, FMT_COMPILE("[{}]"), nullptr);
  EXPECT_EQ(surrounded.size(), result.size);
  EXPECT_EQ(buffer + 5, result.out);
  EXPECT_EQ(surrounded, std::string(buffer, 5));
  EXPECT_EQ('x', buffer[5]);

  buffer[3] = 'x';
  result = fmt::format_to_n(out, 3, FMT_COMPILE("[{}]"), nullptr);
  EXPECT_EQ(surrounded.size(), result.size);
  EXPECT_EQ(buffer + 3, result.out);
  EXPECT_EQ(surrounded.substr(0, 3), std::string(buffer, 3));
  EXPECT_EQ('x', buffer[3]);

  char sentinel = 'x';
  result = fmt::format_to_n(&sentinel, 0, FMT_COMPILE("[{}]"), nullptr);
  EXPECT_EQ(surrounded.size(), result.size);
  EXPECT_EQ(&sentinel, result.out);
  EXPECT_EQ('x', sentinel);

  EXPECT_EQ(bare.size(), fmt::formatted_size(FMT_COMPILE("{}"), nullptr));
  EXPECT_EQ(surrounded.size(),
            fmt::formatted_size(FMT_COMPILE("[{}]"), nullptr));

  const char* text = "test";
  EXPECT_EQ("[test]", fmt::format(FMT_COMPILE("[{}]"), text));
  EXPECT_EQ("[test]",
            fmt::format(FMT_COMPILE("[{}]"), std::string("test")));
  const void* pointer = &sentinel;
  EXPECT_EQ(fmt::format(fmt::runtime("[{}]"), pointer),
            fmt::format(FMT_COMPILE("[{}]"), pointer));
  EXPECT_EQ(surrounded, fmt::format(FMT_COMPILE("[{}]"),
                                   static_cast<const void*>(nullptr)));
}

